-- ============================================================
-- Sistem Pembayaran SPP Sekolah - PHP Native + MySQL
-- Import lewat phpMyAdmin atau:  mysql -u root -p < database/spp_sekolah.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS spp_sekolah CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE spp_sekolah;

DROP TABLE IF EXISTS pembayaran;
DROP TABLE IF EXISTS transaksi;
DROP TABLE IF EXISTS tarif;
DROP TABLE IF EXISTS siswa;
DROP TABLE IF EXISTS kelas;
DROP TABLE IF EXISTS tahun_ajaran;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama_sekolah VARCHAR(150) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30),
  kepala_sekolah VARCHAR(100),
  bendahara VARCHAR(100),
  tanggal_jatuh_tempo TINYINT NOT NULL DEFAULT 10
) ENGINE=InnoDB;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','bendahara') NOT NULL DEFAULT 'bendahara',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE tahun_ajaran (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(20) NOT NULL UNIQUE,      -- 2026/2027
  tahun_mulai SMALLINT NOT NULL,         -- 2026 (Juli 2026 - Juni 2027)
  aktif TINYINT(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE kelas (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(20) NOT NULL UNIQUE,
  tingkat TINYINT NOT NULL,
  wali_kelas VARCHAR(100)
) ENGINE=InnoDB;

CREATE TABLE tarif (
  id INT AUTO_INCREMENT PRIMARY KEY,
  tahun_ajaran_id INT NOT NULL,
  tingkat TINYINT NOT NULL,
  nominal INT NOT NULL,
  UNIQUE KEY uk_tarif (tahun_ajaran_id, tingkat),
  FOREIGN KEY (tahun_ajaran_id) REFERENCES tahun_ajaran(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE siswa (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nis VARCHAR(20) NOT NULL UNIQUE,
  nama VARCHAR(100) NOT NULL,
  jk ENUM('L','P') NOT NULL,
  kelas_id INT,
  nama_wali VARCHAR(100),
  telp_wali VARCHAR(20),
  potongan_persen TINYINT NOT NULL DEFAULT 0,   -- beasiswa / keringanan
  status ENUM('aktif','lulus','keluar') NOT NULL DEFAULT 'aktif',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (kelas_id) REFERENCES kelas(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE transaksi (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  siswa_id INT NOT NULL,
  tahun_ajaran_id INT NOT NULL,
  total INT NOT NULL,
  tgl_bayar DATE NOT NULL,
  metode ENUM('Tunai','Transfer') NOT NULL DEFAULT 'Tunai',
  user_id INT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX (tgl_bayar),
  FOREIGN KEY (siswa_id) REFERENCES siswa(id),
  FOREIGN KEY (tahun_ajaran_id) REFERENCES tahun_ajaran(id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Satu baris per bulan yang dibayar; UNIQUE mencegah bulan yang sama dibayar dua kali
CREATE TABLE pembayaran (
  id INT AUTO_INCREMENT PRIMARY KEY,
  transaksi_id INT NOT NULL,
  siswa_id INT NOT NULL,
  tahun_ajaran_id INT NOT NULL,
  bulan TINYINT NOT NULL,
  nominal INT NOT NULL,
  UNIQUE KEY uk_bulan (siswa_id, tahun_ajaran_id, bulan),
  FOREIGN KEY (transaksi_id) REFERENCES transaksi(id) ON DELETE CASCADE,
  FOREIGN KEY (siswa_id) REFERENCES siswa(id),
  FOREIGN KEY (tahun_ajaran_id) REFERENCES tahun_ajaran(id)
) ENGINE=InnoDB;


