-- Tahun ajaran contoh menyesuaikan tanggal import (Juli s.d. Juni)
SET @ty := YEAR(CURDATE()) - IF(MONTH(CURDATE()) < 7, 1, 0);
UPDATE tahun_ajaran SET tahun_mulai = @ty - 1, nama = CONCAT(@ty - 1, '/', @ty) WHERE id = 1;
UPDATE tahun_ajaran SET tahun_mulai = @ty, nama = CONCAT(@ty, '/', @ty + 1) WHERE id = 2;


-- Buang pembayaran contoh yang tanggalnya belum terjadi
DELETE FROM transaksi WHERE tgl_bayar > CURDATE();
SET @n := 0;
UPDATE transaksi SET kode = CONCAT('KW-', DATE_FORMAT(tgl_bayar, '%y%m'), '-', LPAD(@n := @n + 1, 4, '0')), created_at = tgl_bayar ORDER BY tgl_bayar, id;
